"""Raw HTTP to Sharadar's documented API (sharadar.com/docs/getting-started, read 2026-10-18).

CSV, `limit`/`skip` paging (default limit 10000), `api_key` as a query parameter. Note `from` defaults to
one year ago on stocks, actions and sp500, so every call here passes it. Errors never carry the URL.
"""
from __future__ import annotations

import csv
import io
import json
import os
import urllib.error
import urllib.parse
import urllib.request

BASE = os.environ.get("SHARADAR_BASE_URL", "https://api.sharadar.com/v1.0/data")
NDL = os.environ.get("NDL_BASE_URL", "https://data.nasdaq.com/api/v3/datatables/SHARADAR")
PAGE = 10000
START = "1997-12-01"


class VendorError(Exception):
    """An HTTP refusal: the status and the vendor's error code, never the request."""

    def __init__(self, status: int, vendor_code: str):
        super().__init__(f"HTTP {status} {vendor_code}")
        self.code = status


def get(url: str) -> tuple[int, str]:
    try:
        with urllib.request.urlopen(url, timeout=120) as r:
            return r.status, r.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode(errors="replace")


def error_code(body: str) -> str:
    try:
        return str(json.loads(body)["quandl_error"]["code"])
    except (ValueError, KeyError, TypeError):
        return ""


def url(table: str, **params) -> str:
    q = {**params, "api_key": os.environ["SHARADAR_API_KEY"], "format": "csv"}
    return f"{BASE}/{table}?{urllib.parse.urlencode(q)}"


def ndl_url(table: str, **params) -> str:
    q = {**params, "api_key": os.environ["SHARADAR_API_KEY"], "qopts.per_page": 1}
    return f"{NDL}/{table}.csv?{urllib.parse.urlencode(q)}"


def rows(table: str, **params) -> list[dict]:
    """Every row of `table` matching `params`, page by page."""
    out, skip = [], 0
    while True:
        status, body = get(url(table, **params, limit=PAGE, skip=skip))
        if status != 200:
            raise VendorError(status, error_code(body))
        page = list(csv.DictReader(io.StringIO(body)))
        out += page
        if len(page) < PAGE:
            return out
        skip += PAGE

